from typing import List, Tuple

def find_farthest_points(N: int, points: List[Tuple[int, int]]) -> List[int]:
    def calculate_distance(point1, point2):
        return ((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2) ** 0.5

    result = []
    for i in range(N):
        far_d, far_id = -1, -1
        for j in range(N):
            if i == j: continue
            d = calculate_distance(points[i], points[j])
            if d > far_d:
                far_d, far_id = d, j + 1
            elif d == far_d:
                far_id = min(far_id, j + 1)
        result.append(far_id)
    return result
